import pandas as pd

file_path = 'nasa_budget_recovered.xlsx'

try:
    all_sheets = pd.read_excel(file_path, sheet_name=None, header=None)

    missing_count = 0
    for sheet_name, df in all_sheets.items():
        # Iterate through all cells
        for row_idx, row in df.iterrows():
            for col_idx, value in row.items():
                if str(value).strip() == "???":
                    print(f"Missing value found in '{sheet_name}': Row {row_idx}, Col {col_idx}")
                    missing_count += 1

    if missing_count == 0:
        print("Success: No missing values found in the recovered file.")
    else:
        print(f"Failure: Found {missing_count} missing values.")

except Exception as e:
    print(f"Error reading Excel file: {e}")

